def print_config(config, indent=0):
    """설정을 보기 좋게 출력하는 함수"""
    for key, value in config.items():
        print("  " * indent + f"{key}:", end="")
        
        if isinstance(value, dict):
            print()
            print_config(value, indent + 1)
        else:
