print(f"존재하지 않는 설정: {get_config_value(app_config, 'cache', 'redis', 'host')}")

# 설정 업데이트
def update_config_value(config, value, *path):
    """설정값 업데이트"""
    current = config
    for key in path[:-1]:
        if key not in current:
            current[key] = {}
        current = current[key]
    
    current[path[-1]] = value

